SELECT attachment_id, mail_id, uploader_id, file_name, file_path, file_size, file_type, upload_time
FROM attachment
WHERE attachment_id = #{attachmentId}

SELECT COUNT(1) > 0
FROM mail
WHERE mail_id = #{mailId}
  AND sender_id = #{userId}
  AND sender_deleted = FALSE
  AND mail_status = 1

SELECT COUNT(1) > 0
FROM mail m
WHERE m.mail_id = #{mailId}
  AND m.mail_status = 1
  AND (
      m.sender_id = #{userId}
      OR EXISTS (
          SELECT 1
          FROM mail_receiver mr
          WHERE mr.mail_id = m.mail_id
            AND mr.receiver_id = #{userId}
            AND mr.receiver_type IN ('TO', 'CC', 'BCC')
      )
  )

mapper.update:
UPDATE mail
SET has_attachment = TRUE
WHERE mail_id = #{mailId}
